//! Golden test: the Rust payload encoder produces the same bytes as the Python engine.
//!
//! `tests/golden/payload_cases.json` is generated by the Python reference implementation
//! (`python -m tests.helpers.payload_golden`, kept current by
//! `tests/unit/test_payload_golden.py`): inputs plus `encode(build_payload(...))`.

use chrono::{DateTime, Utc};
use serde_json::Value as Json;

use opencap_core::config::{Device, PayloadCfg};
use opencap_core::health::{HealthStatus, State};
use opencap_core::store::Snapshot;
use opencap_core::value::{Quality, TagValue, Value};
use opencap_core::FIRM_VERSION;
use opencap_north::payload::{build_payload, encode, encode_status};

fn dec_value(v: &Json) -> Option<Value> {
    let t = v["t"].as_str().unwrap();
    let x = &v["v"];
    Some(match t {
        "none" => return None,
        "bool" => Value::Bool(x.as_bool().unwrap()),
        "int" => {
            let s = x.as_str().unwrap();
            match s.parse::<i64>() {
                Ok(i) => Value::Int(i),
                Err(_) => Value::UInt(s.parse::<u64>().unwrap()),
            }
        }
        "float" => Value::Float(x.as_str().unwrap().parse::<f64>().unwrap()),
        "str" => Value::Str(x.as_str().unwrap().to_string()),
        "list" => Value::List(x.as_array().unwrap().iter().map(|e| dec_value(e).unwrap()).collect()),
        other => panic!("unknown tag {other}"),
    })
}

fn quality(s: &str) -> Quality {
    match s {
        "good" => Quality::Good,
        "bad_comm" => Quality::BadComm,
        "bad_config" => Quality::BadConfig,
        "bad_decode" => Quality::BadDecode,
        "stale" => Quality::Stale,
        other => panic!("quality {other}"),
    }
}

fn ts(v: &Json) -> Option<DateTime<Utc>> {
    v.as_str().map(|s| DateTime::parse_from_rfc3339(s).unwrap().with_timezone(&Utc))
}

fn load() -> Json {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/golden/payload_cases.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

#[test]
fn payload_bytes_match_python() {
    let golden = load();
    let py_version = golden["firm_version"].as_str().unwrap();
    let cases = golden["payload"].as_array().unwrap();
    assert!(cases.len() > 200);
    let mut failures = Vec::new();
    for (i, case) in cases.iter().enumerate() {
        let device: Device = serde_json::from_value(case["device"].clone()).unwrap();
        let cfg: PayloadCfg = serde_json::from_value(case["cfg"].clone()).unwrap();
        let values = Snapshot::from_pairs(
            &device.id,
            case["values"].as_object().unwrap().iter().map(|(name, tv)| {
                (
                    name.clone(),
                    TagValue::new(
                        dec_value(&tv["value"]),
                        quality(tv["quality"].as_str().unwrap()),
                        ts(&tv["source_ts"]),
                    ),
                )
            }),
        );
        let p = build_payload(&device, &values, &cfg, case["is_secure"].as_bool().unwrap(), ts(&case["now"])).unwrap();
        let got = String::from_utf8(encode(&p)).unwrap();
        // Same input, same bytes; FirmVersion follows each engine's own release number.
        let expected = case["expected"]
            .as_str()
            .unwrap()
            .replace(&format!("\"FirmVersion\":\"{py_version}\""), &format!("\"FirmVersion\":\"{FIRM_VERSION}\""));
        if got != expected {
            failures.push(format!("case {i}:\n  python: {expected}\n  rust:   {got}"));
        }
    }
    assert!(failures.is_empty(), "{} of {} cases differ:\n{}", failures.len(), cases.len(), failures.join("\n"));
}

#[test]
fn status_bytes_match_python() {
    for case in load()["status"].as_array().unwrap() {
        let s = &case["status"];
        let state = match s["state"].as_str().unwrap() {
            "ok" => State::Ok,
            "demoted" => State::Demoted,
            _ => State::Offline,
        };
        let st = HealthStatus {
            state,
            last_good: s["last_good"].as_str().map(String::from),
            errors: s["errors"].as_u64().unwrap(),
        };
        assert_eq!(String::from_utf8(encode_status(&st)).unwrap(), case["expected"].as_str().unwrap());
    }
}

#[test]
fn same_release_number_as_python() {
    // Not required for byte identity (the test above substitutes it), but the two engines
    // ship as one product: keep the version numbers in step while Python is the reference.
    assert_eq!(load()["firm_version"].as_str().unwrap(), FIRM_VERSION);
}
